 announce:"جديد · <b>إعادة اتصال flash-safe</b> — الجلسة المنقطعة تُستأنف تلقائيًا.", announce_link:"اعرف أكثر",
 nav_platform:"المنصة", nav_security:"الأمان", nav_modes:"أوضاع التشغيل", nav_how:"كيف تعمل", nav_contact:"تواصل", nav_download:"تنزيل",
 hero_badge:"بنية مشاركة USB / ADB",
