// ── generare ────────────────────────────────────────────────────────────────
const tpl = readFileSync(join(DIR, "_template.html"), "utf8");
const pathOf = (code) => (code === "en" ? "/" : `/${code}/`);

function hreflang(current) {
  const rows = LANGS.map(([c]) => `<link rel="alternate" hreflang="${c}" href="${BASE}${pathOf(c)}">`);
  rows.push(`<link rel="alternate" hreflang="x-default" href="${BASE}/">`);
  return rows.join("\n");
}
function switcher(current) {
  const cur = LANGS.find(([c]) => c === current);
  const items = LANGS.map(([c, label]) =>
    `<a href="${pathOf(c)}"${c === current ? ' aria-current="true"' : ""}>${label}</a>`).join("");
  return `<details class="langsel"><summary>${cur[1]}</summary><div class="menu">${items}</div></details>`;
}

let count = 0;
for (const [code] of LANGS) {
  const dict = T[code];
  if (!dict) { console.warn(`(sar ${code} — fără dicționar)`); continue; }
  let html = tpl
    .replaceAll("{{LANG}}", code)
    .replaceAll("{{DIR}}", RTL.has(code) ? "rtl" : "ltr")
    .replaceAll("{{CANONICAL}}", BASE + pathOf(code))
    .replaceAll("{{HREFLANG}}", hreflang(code))
    .replaceAll("{{SWITCHER}}", switcher(code))
    .replaceAll("{{DL_WIN}}", DL.win)
    .replaceAll("{{DL_MAC}}", DL.mac)
    .replaceAll("{{DL_LINUX}}", DL.linux);
  for (const [k, v] of Object.entries(dict)) html = html.replaceAll(`{{${k}}}`, v);
  // orice placeholder rămas = cheie lipsă
  const left = [...html.matchAll(/\{\{(\w+)\}\}/g)].map((m) => m[1]);
  if (left.length) console.warn(`  ${code}: chei lipsă → ${[...new Set(left)].join(", ")}`);
  const out = code === "en" ? join(DIR, "index.html") : join(DIR, code, "index.html");
  mkdirSync(dirname(out), { recursive: true });
  writeFileSync(out, html);
  count++;
}
console.log(`✓ generat ${count} pagini (en la rădăcină, restul în /<cod>/)`);
